from __future__ import annotations

import json
from pathlib import Path

import pytest

from converse_diarization.report import (
    ReportError,
    build_payload,
    discover_runs,
    render_html,
    run_payload,
    write_report,
)

HEADER_COMMENT = (
    "<!-- Generated by converse-diarization, Ocular AI's open-source Converse-Diarization harness (MIT License): "
    "https://github.com/OcularEngineering/converse-diarization -->"
)


def _der(missed: float, false_alarm: float, confusion: float, reference: float, *, collar: float, assignment) -> dict:
    errors = missed + false_alarm + confusion
    return {
        "rate": errors / reference,
        "missed_s": missed,
        "false_alarm_s": false_alarm,
        "confusion_s": confusion,
        "reference_s": reference,
        "errors_s": errors,
        "collar_s": collar,
        "assignment": assignment,
    }


def _conversation(conversation: str, *, missed: float, false_alarm: float, confusion: float, extra: bool) -> dict:
    reference = 20.0
    assignment = [["ch1", "SPEAKER_00"], ["ch2", "SPEAKER_01"]]
    hypothesis_segments = [
        {"speaker": "SPEAKER_00", "start_s": 0.2, "end_s": 5.1},
        {"speaker": "SPEAKER_01", "start_s": 5.0, "end_s": 10.8},
        {"speaker": "SPEAKER_00", "start_s": 11.0, "end_s": 14.0},
    ]
    hypothesis_time = {"SPEAKER_00": 7.9, "SPEAKER_01": 5.8}
    if extra:
        hypothesis_segments.append({"speaker": "SPEAKER_02", "start_s": 14.5, "end_s": 16.0})
        hypothesis_time["SPEAKER_02"] = 1.5
    jer_rates = {"ch1": (missed + confusion) / reference, "ch2": (false_alarm + confusion) / reference}
    return {
        "conversation": conversation,
        "language": "en",
        "duration_s": 16.0,
        "overlap_ratio": 0.05 if conversation.endswith("1") else 0.25,
        "tier": "low" if conversation.endswith("1") else "high",
        "latency_s": 1.5,
        "granularity": "segment",
        "der": _der(missed, false_alarm, confusion, reference, collar=0.0, assignment=assignment),
        "der_collar": _der(
            missed / 2, false_alarm / 2, confusion / 2, reference - 2, collar=0.25, assignment=assignment
        ),
        "jer": {
            "rate": sum(jer_rates.values()) / 2,
            "error_sum": sum(jer_rates.values()),
            "reference_speakers": 2,
            "per_speaker": jer_rates,
            "assignment": assignment,
        },
        "speaker_count": {
            "reference": 2,
            "hypothesis": 3 if extra else 2,
            "correct": not extra,
            "absolute_error": 1 if extra else 0,
        },
        "speaking_time": {"reference": {"ch1": 10.0, "ch2": 10.0}, "hypothesis": hypothesis_time},
        "reference_segments": [
            {"speaker": "ch1", "start_s": 0.0, "end_s": 5.0},
            {"speaker": "ch2", "start_s": 4.5, "end_s": 10.5},
            {"speaker": "ch1", "start_s": 11.0, "end_s": 15.0},
        ],
        "hypothesis_segments": hypothesis_segments,
    }


def _write_run(root: Path, name: str, rows: list[dict], *, total: int | None = None, notes: str = "") -> Path:
    run_dir = root / name
    run_dir.mkdir(parents=True)
    with (run_dir / "scores.jsonl").open("w", encoding="utf-8") as handle:
        for row in rows:
            handle.write(json.dumps(row) + "\n")

    def pooled(key: str) -> dict:
        fields = ("missed_s", "false_alarm_s", "confusion_s", "reference_s", "errors_s")
        sums = {field: sum(row[key][field] for row in rows) for field in fields}
        return {"rate": sums["errors_s"] / sums["reference_s"], **sums}

    tiers = {}
    for tier in sorted({row["tier"] for row in rows}):
        in_tier = [row for row in rows if row["tier"] == tier]
        sums = {
            field: sum(row["der"][field] for row in in_tier)
            for field in ("missed_s", "false_alarm_s", "confusion_s", "reference_s", "errors_s")
        }
        tiers[tier] = {"conversations": len(in_tier), "der": {"rate": sums["errors_s"] / sums["reference_s"], **sums}}
    correct = sum(1 for row in rows if row["speaker_count"]["correct"])
    total = len(rows) if total is None else total
    summary = {
        "schema": 1,
        "scored_at": "2026-10-09T12:00:00Z",
        "model": {
            "name": name,
            "display_name": name.replace("-", " ").title(),
            "vendor": "Vendor " + name[-1].upper(),
            "provider": "http",
            "model": f"{name}-v1",
            "env": {},
            "options": {},
            "href": f"https://example.com/{name}",
            "notes": notes,
        },
        "model_digest": f"digest-{name}",
        "dataset": {"root": "data", "digest": "dataset-digest", "source": {"kind": "local"}},
        "merge_gap_s": 0.2,
        "collar_s": 0.25,
        "der": pooled("der"),
        "der_collar": pooled("der_collar"),
        "jer": {"rate": sum(row["jer"]["rate"] for row in rows) / len(rows), "conversations": len(rows)},
        "speaker_count": {
            "accuracy": correct / len(rows),
            "correct": correct,
            "total": len(rows),
            "mean_absolute_error": sum(row["speaker_count"]["absolute_error"] for row in rows) / len(rows),
        },
        "tiers": tiers,
        "conversations": {"scored": len(rows), "missing": total - len(rows), "total": total},
        "failures": total - len(rows),
        "conversation_scores": [
            {key: value for key, value in row.items() if key not in {"reference_segments", "hypothesis_segments"}}
            for row in rows
        ],
    }
    (run_dir / "summary.json").write_text(json.dumps(summary, indent=2), encoding="utf-8")
    return run_dir


@pytest.fixture
def runs(tmp_path):
    root = tmp_path / "runs"
    good = _write_run(
        root,
        "model-a",
        [
            _conversation("conv-1", missed=1.0, false_alarm=0.5, confusion=0.5, extra=False),
            _conversation("conv-2", missed=2.0, false_alarm=1.0, confusion=1.0, extra=False),
        ],
        notes="clean </script><b>run</b>",
    )
    worse = _write_run(
        root,
        "model-b",
        [
            _conversation("conv-1", missed=3.0, false_alarm=2.0, confusion=1.0, extra=True),
            _conversation("conv-2", missed=4.0, false_alarm=2.0, confusion=2.0, extra=False),
        ],
    )
    return root, good, worse


def test_discover_runs_finds_scored_directories(runs, tmp_path):
    root, good, worse = runs
    (root / "notes.txt").write_text("x", encoding="utf-8")
    (root / "unscored").mkdir()
    assert discover_runs(root) == [good, worse]
    assert discover_runs(tmp_path / "missing") == []


def test_run_payload_converts_rates_and_keeps_timelines(runs):
    _, good, worse = runs
    run = run_payload(worse)
    assert run["name"] == "model-b" and run["display_name"] == "Model B" and run["vendor"] == "Vendor B"
    assert run["model"] == "model-b-v1" and run["href"] == "https://example.com/model-b"
    # (6 + 8) seconds of error over 40 seconds of reference speech.
    assert run["der"] == pytest.approx(35.0)
    assert run["breakdown"] == {"missed": 17.5, "false_alarm": 10.0, "confusion": 7.5}
    assert run["speaker_count"]["accuracy"] == 50.0 and run["speaker_count"]["correct"] == 1
    assert set(run["tiers"]) == {"low", "high"} and run["tiers"]["low"]["der"] == pytest.approx(30.0)
    assert run["conversations_scored"] == 2 and run["conversations_total"] == 2 and run["complete"]
    first = run["conversations"][0]
    assert first["id"] == "conv-1" and first["tier"] == "low" and first["overlap_ratio"] == 5.0
    assert first["der"] == pytest.approx(30.0) and first["der_collar"] == pytest.approx(3.0 / 18 * 100, abs=0.01)
    assert first["speakers"] == {"reference": 2, "hypothesis": 3, "correct": False, "absolute_error": 1}
    assert first["assignment"] == [["ch1", "SPEAKER_00"], ["ch2", "SPEAKER_01"]]
    assert len(first["reference_segments"]) == 3 and len(first["hypothesis_segments"]) == 4
    assert first["hypothesis_segments"][-1]["speaker"] == "SPEAKER_02"
    assert first["speaking_time"]["hypothesis"]["SPEAKER_02"] == 1.5
    assert run_payload(good)["der"] == pytest.approx(15.0)


def test_build_payload_orders_by_der_and_flags_incomplete(runs, tmp_path):
    root, good, worse = runs
    partial = _write_run(
        root,
        "model-c",
        [_conversation("conv-1", missed=0.1, false_alarm=0.1, confusion=0.0, extra=False)],
        total=2,
    )
    payload = build_payload([worse, partial, good], sample_label="Smoke sample")
    assert payload["benchmark"] == "Converse-Diarization" and payload["family"] == "Converse"
    assert payload["sampleLabel"] == "Smoke sample" and payload["generated"]
    assert payload["dataset"] == {"digest": "dataset-digest", "conversations": 2}
    # Lowest DER first; the incomplete run sinks to the bottom even though its DER is tiny.
    assert [run["name"] for run in payload["runs"]] == ["model-a", "model-b", "model-c"]
    assert [run["complete"] for run in payload["runs"]] == [True, True, False]
    assert payload["runs"][-1]["conversations_missing"] == 1 and payload["runs"][-1]["failures"] == 1


def test_render_html_inlines_payload(runs):
    _, good, worse = runs
    payload = build_payload([good, worse])
    html = render_html(payload)
    assert "__PAYLOAD__" not in html
    assert HEADER_COMMENT in html
    assert "<title>Converse-Diarization · Ocular AI Converse</title>" in html
    assert "Model A" in html and "Model B" in html and '"model-b-v1"' in html
    assert '"breakdown": {"missed": 17.5' in html
    # The payload's `</script>` must not close the page's script element.
    assert "<\\/script><b>run<\\/b>" in html and html.count("</script>") == 1


def test_write_report_and_missing_summary(runs, tmp_path):
    _, good, worse = runs
    page = write_report([good, worse], tmp_path / "reports" / "index.html")
    assert page.is_file() and page.read_text(encoding="utf-8").startswith("<!DOCTYPE html>")
    empty = render_html(build_payload([]))
    assert '"runs": []' in empty
    bare = tmp_path / "runs" / "bare"
    bare.mkdir()
    with pytest.raises(ReportError, match="summary.json"):
        build_payload([bare])
